1	package main
2	
3	import (
4		"errors"
5		"flag"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10		"time"
11	)
12	
13	const appName = "caretrack"
14	
15	const helpText = `caretrack — 本地设备资产登记与维修工单闭环工具
16	
17	数据保存在本地目录，无外部服务依赖，仅支持单进程顺序调用。
18	
19	用法:
20	  caretrack <命令> [参数]
21	
22	命令:
23	  register   登记资产（企业资产编号、名称、位置）
24	  list       列出全部资产及当前状态
25	  detail     查看资产详情及其未关闭工单编号
26	  report     对资产报修，创建工单，资产转为“维修中”
27	  assign     为未关闭工单派工或转派维修人员
28	  ticket     按工单编号查询工单状态与负责人
29	  close      关闭工单并填写维修结果，设备恢复“可用”
30	  cancel     取消误报或不再需要维修的未关闭工单，设备恢复“可用”
31	  history    按资产查看维修履历（报修、派工、关闭、取消事件）
32	  downtime   查询时间窗口内的设备维修停机时长（单项或全部资产）
33	  help       显示本帮助
34	
35	各命令参数:
36	  register --asset-id 编号 --name 名称 --location 位置 [--data-dir 目录]
37	  list                                                        [--data-dir 目录]
38	  detail   --asset-id 编号                                    [--data-dir 目录]
39	  report   --asset-id 编号 --description 故障描述 --request-id 请求标识
40	                                                              [--data-dir 目录]
41	  assign   --ticket-id 工单编号 --assignee 维修人员 --note 说明  [--data-dir 目录]
42	  ticket   --ticket-id 工单编号                                 [--data-dir 目录]
43	  close    --ticket-id 工单编号 --repair-result 维修结果       [--data-dir 目录]
44	  cancel   --ticket-id 工单编号 --reason 取消理由              [--data-dir 目录]
45	  history  --asset-id 编号                                    [--data-dir 目录]
46	  downtime --start 起点 --end 终点 [--asset-id 编号]          [--data-dir 目录]
47	
48	通用参数:
49	  --data-dir 目录   本地数据目录，默认 ".caretrack"；不同目录数据互不影响，
50	                    目录不存在时会在首次成功写入时自动初始化
51	
52	业务规则:
53	  - 资产编号、名称、位置均不能为空；同一数据目录内资产编号唯一，新资产为“可用”。
54	  - 每项资产最多有一张未关闭工单；未知资产、空故障描述、资产已有未关闭工单时
55	    报修失败，不改变状态与履历。
56	  - --request-id 由调用方提供且非空，仅用于同一数据目录内的报修去重，不作为
57	    资产或工单编号：相同标识、资产、描述再次提交返回原工单及当前状态，不新增
58	    记录；同一标识搭配不同资产或描述将被拒绝；原工单关闭或取消后重放仍返回原工单，
59	    不重开旧单，也不影响新单。
60	  - 仅未关闭工单可派工：没有负责人时首次派工，已有负责人时转派给不同人员。
61	    维修人员标识只是本地文本记录（非人员账户），与派工说明均不能为空；
62	    成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为
63	    “未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单编号，
64	    不改变资产状态或报修请求绑定；未知工单、空人员或说明、重复派给当前
65	    人员、对已关闭或已取消工单派工均失败且不产生履历。工单关闭或取消后
66	    保留最后负责人与派工履历。
67	  - 仅未关闭工单可关闭，维修结果不能为空；未知工单、重复关闭均失败。
68	  - 仅未关闭工单可取消，取消理由不能为空；取消后工单进入“已取消”终态，保存取消
69	    理由与时间，资产恢复“可用”，可再次报修。取消不代表维修完成，不填写维修结果，
70	    不删除工单、履历或请求绑定，工单编号不回退也不复用；已取消工单不能关闭或再次
71	    取消，已关闭工单也不能取消。
72	  - downtime 为只读统计，不写文件、不初始化目录、不追加履历。--start/--end 为
73	    带时区的 RFC3339 时刻（可含小数秒），起点须早于终点；窗口包含起点、不包含
74	    终点，按实际时刻比较。停机自工单报修履历时间起，至关闭或取消履历时间止
75	    （取消前的占用同样计入）；派工、转派不另起区间；未关闭工单暂算到窗口终点，
76	    不读取运行时刻，也不改变状态。只统计工单区间与窗口的交集，窗口外及零长度
77	    不贡献；同一资产多张工单的重叠交集取并集，不直接相加。每项资产合计后向下
78	    取整为秒，并输出全部所选资产秒数之和；没有停机的资产显示零。不给 --asset-id
79	    时统计全部资产并按编号字典序排列，空库明确提示无记录并显示零合计。若所选
80	    资产任一终结工单的结束履历时间早于报修履历时间（即使该单在窗口外、结束
81	    等于开始合法），整次统计失败，指出资产与工单，不输出部分结果。
82	
83	无参数、--help、-h 显示本帮助；参数错误或业务失败以非零退出码结束并说明原因。
84	参数错误退出码为 2；未知资产、上述时间异常及数据读取失败退出码为 1。
85	`
86	
87	type cmdOptions struct {
88		dataDir string
89	}
90	
91	func printHelp(w io.Writer) {
92		fmt.Fprint(w, helpText)
93	}
94	
95	func main() {
96		os.Exit(run(os.Args[1:], os.Stdout, os.Stderr))
97	}
98	
99	func run(args []string, stdout, stderr io.Writer) int {
100		if len(args) == 0 {
101			printHelp(stdout)
102			return 0
103		}
104		switch args[0] {
105		case "--help", "-h", "help":
106			if len(args) > 1 {
107				fmt.Fprintf(stderr, "%s: help 不接受额外参数\n", appName)
108				return 2
109			}
110			printHelp(stdout)
111			return 0
112		}
113	
114		var err error
115		switch args[0] {
116		case "register":
117			err = cmdRegister(args[1:], stdout)
118		case "list":
119			err = cmdList(args[1:], stdout)
120		case "detail":
121			err = cmdDetail(args[1:], stdout)
122		case "report":
123			err = cmdReport(args[1:], stdout)
124		case "assign":
125			err = cmdAssign(args[1:], stdout)
126		case "ticket":
127			err = cmdTicket(args[1:], stdout)
128		case "close":
129			err = cmdClose(args[1:], stdout)
130		case "cancel":
131			err = cmdCancel(args[1:], stdout)
132		case "history":
133			err = cmdHistory(args[1:], stdout)
134		case "downtime":
135			err = cmdDowntime(args[1:], stdout)
136		default:
137			fmt.Fprintf(stderr, "%s: 未知命令 %q，使用 --help 查看帮助\n", appName, args[0])
138			return 2
139		}
140		if err != nil {
141			if errors.Is(err, flag.ErrHelp) {
142				return 0
143			}
144			var ue *usageError
145			if errors.As(err, &ue) {
146				fmt.Fprintf(stderr, "%s: %s\n", appName, ue.Error())
147				return 2
148			}
149			fmt.Fprintf(stderr, "%s: %s\n", appName, friendlyErr(err.Error()))
150			return 1
151		}
152		return 0
153	}
154	
155	// friendlyErr 去掉内部哨兵错误（errNotFound/errConflict）的英文前缀。
156	func friendlyErr(msg string) string {
157		for _, p := range []string{"not found: ", "conflict: "} {
158			if strings.HasPrefix(msg, p) {
159				return msg[len(p):]
160			}
161		}
162		return msg
163	}
164	
165	type usageError struct{ msg string }
166	
167	func (e *usageError) Error() string { return e.msg }
168	
169	// newFlagSet 为子命令准备参数解析器：--help/-h 输出帮助并返回 flag.ErrHelp，
170	// 其余参数错误转成 *usageError（退出码 2）。
171	func newFlagSet(name string, opts *cmdOptions) *flag.FlagSet {
172		fs := flag.NewFlagSet(name, flag.ContinueOnError)
173		fs.SetOutput(os.Stdout)
174		fs.Usage = func() {
175			fmt.Fprintf(os.Stdout, "用法: caretrack %s [参数]\n\n", name)
176			fs.PrintDefaults()
177		}
178		fs.StringVar(&opts.dataDir, "data-dir", ".caretrack", "本地数据目录")
179		return fs
180	}
181	
182	func parseFlags(fs *flag.FlagSet, args []string) error {
183		if err := fs.Parse(args); err != nil {
184			if errors.Is(err, flag.ErrHelp) {
185				return err
186			}
187			return &usageError{msg: err.Error()}
188		}
189		if fs.NArg() > 0 {
190			return &usageError{msg: fmt.Sprintf("命令 %s 不接受位置参数: %v", fs.Name(), fs.Args())}
191		}
192		return nil
193	}
194	
195	func requireFlag(fs *flag.FlagSet, value, flagName string) error {
196		if value == "" {
197			return &usageError{msg: fmt.Sprintf("命令 %s 缺少必填参数 --%s", fs.Name(), flagName)}
198		}
199		return nil
200	}
201	
202	func cmdRegister(args []string, w io.Writer) error {
203		var opts cmdOptions
204		var id, name, location string
205		fs := newFlagSet("register", &opts)
206		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填，同一数据目录内唯一）")
207		fs.StringVar(&name, "name", "", "资产名称（必填）")
208		fs.StringVar(&location, "location", "", "资产位置（必填）")
209		if err := parseFlags(fs, args); err != nil {
210			return err
211		}
212		if err := requireFlag(fs, id, "asset-id"); err != nil {
213			return err
214		}
215		if err := requireFlag(fs, name, "name"); err != nil {
216			return err
217		}
218		if err := requireFlag(fs, location, "location"); err != nil {
219			return err
220		}
221	
222		s, err := openStore(opts.dataDir)
223		if err != nil {
224			return err
225		}
226		asset, err := s.registerAsset(id, name, location)
227		if err != nil {
228			return err
229		}
230		if err := s.save(); err != nil {
231			return err
232		}
233		fmt.Fprintf(w, "已登记资产 %s\n", asset.ID)
234		fmt.Fprintf(w, "名称: %s\n", asset.Name)
235		fmt.Fprintf(w, "位置: %s\n", asset.Location)
236		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
237		return nil
238	}
239	
240	func cmdList(args []string, w io.Writer) error {
241		var opts cmdOptions
242		fs := newFlagSet("list", &opts)
243		if err := parseFlags(fs, args); err != nil {
244			return err
245		}
246		s, err := openStore(opts.dataDir)
247		if err != nil {
248			return err
249		}
250		assets := s.data.Assets
251		if len(assets) == 0 {
252			fmt.Fprintln(w, "没有记录。")
253			return nil
254		}
255		fmt.Fprintf(w, "共 %d 项资产:\n", len(assets))
256		for _, a := range assets {
257			fmt.Fprintf(w, "%s\t%s\t%s\t%s\n", a.ID, a.Name, a.Location, a.Status)
258		}
259		return nil
260	}
