262	func cmdDetail(args []string, w io.Writer) error {
263		var opts cmdOptions
264		var id string
265		fs := newFlagSet("detail", &opts)
266		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
267		if err := parseFlags(fs, args); err != nil {
268			return err
269		}
270		if err := requireFlag(fs, id, "asset-id"); err != nil {
271			return err
272		}
273		s, err := openStore(opts.dataDir)
274		if err != nil {
275			return err
276		}
277		asset := s.findAsset(id)
278		if asset == nil {
279			return fmt.Errorf("未知资产编号 %q", id)
280		}
281		openTicket := s.openTicketOf(asset.ID)
282		fmt.Fprintf(w, "资产编号: %s\n", asset.ID)
283		fmt.Fprintf(w, "名称: %s\n", asset.Name)
284		fmt.Fprintf(w, "位置: %s\n", asset.Location)
285		fmt.Fprintf(w, "当前状态: %s\n", asset.Status)
286		if openTicket == nil {
287			fmt.Fprintln(w, "未关闭工单: 无")
288		} else {
289			fmt.Fprintf(w, "未关闭工单: %s\n", openTicket.ID)
290			fmt.Fprintf(w, "工单负责人: %s\n", assigneeDisplay(openTicket.Assignee))
291		}
292		return nil
293	}
294	
295	// assigneeDisplay 把空负责人显示为“未派工”。
296	func assigneeDisplay(assignee string) string {
297		if assignee == "" {
298			return "未派工"
299		}
300		return assignee
301	}
