303	func cmdReport(args []string, w io.Writer) error {
304		var opts cmdOptions
305		var assetID, description, requestID string
306		fs := newFlagSet("report", &opts)
307		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（必填）")
308		fs.StringVar(&description, "description", "", "故障描述（必填）")
309		fs.StringVar(&requestID, "request-id", "", "调用方提供的非空请求标识，用于报修去重（必填）")
310		if err := parseFlags(fs, args); err != nil {
311			return err
312		}
313		if err := requireFlag(fs, assetID, "asset-id"); err != nil {
314			return err
315		}
316		if err := requireFlag(fs, description, "description"); err != nil {
317			return err
318		}
319		if err := requireFlag(fs, requestID, "request-id"); err != nil {
320			return err
321		}
322	
323		s, err := openStore(opts.dataDir)
324		if err != nil {
325			return err
326		}
327		ticket, replayed, err := s.report(assetID, description, requestID)
328		if err != nil {
329			return err
330		}
331		if !replayed {
332			if err := s.save(); err != nil {
333				return err
334			}
335			fmt.Fprintf(w, "工单编号: %s\n", ticket.ID)
336		} else {
337			fmt.Fprintf(w, "该请求标识已提交过，返回原工单，未重复创建。\n")
338			fmt.Fprintf(w, "工单编号: %s（既有工单）\n", ticket.ID)
339		}
340		fmt.Fprintf(w, "资产编号: %s\n", ticket.AssetID)
341		fmt.Fprintf(w, "工单状态: %s\n", ticket.Status)
342		return nil
343	}
