477	func cmdHistory(args []string, w io.Writer) error {
478		var opts cmdOptions
479		var id string
480		fs := newFlagSet("history", &opts)
481		fs.StringVar(&id, "asset-id", "", "企业资产编号（必填）")
482		if err := parseFlags(fs, args); err != nil {
483			return err
484		}
485		if err := requireFlag(fs, id, "asset-id"); err != nil {
486			return err
487		}
488		s, err := openStore(opts.dataDir)
489		if err != nil {
490			return err
491		}
492		if s.findAsset(id) == nil {
493			return fmt.Errorf("未知资产编号 %q", id)
494		}
495		events := s.eventsOf(id)
496		if len(events) == 0 {
497			fmt.Fprintf(w, "资产 %s 暂无维修履历。\n", id)
498			return nil
499		}
500		fmt.Fprintf(w, "资产 %s 维修履历（共 %d 条）:\n", id, len(events))
501		for _, e := range events {
502			if e.Kind == eventAssign {
503				fmt.Fprintf(w, "[%s] %s 工单 %s: %s -> %s（%s）\n",
504					e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID,
505					assigneeDisplay(e.From), e.To, e.Content)
506				continue
507			}
508			fmt.Fprintf(w, "[%s] %s 工单 %s: %s\n",
509				e.Time.Format("2006-01-02T15:04:05Z07:00"), e.Kind, e.TicketID, e.Content)
510		}
511		return nil
512	}
513	
514	// cmdDowntime 为只读的停机时长统计：先经 openStore 完成整库一致性检查，
515	// 再计算窗口内的停机秒数。无论成功或失败都不保存，因此不写文件、不初始化
516	// 目录、不追加履历、不消耗编号，也不改变报修请求绑定。
517	func cmdDowntime(args []string, w io.Writer) error {
518		var opts cmdOptions
519		var startText, endText, assetID string
520		fs := newFlagSet("downtime", &opts)
521		fs.StringVar(&startText, "start", "", "窗口起点（必填，带时区的 RFC3339 时刻，可含小数秒；包含）")
522		fs.StringVar(&endText, "end", "", "窗口终点（必填，带时区的 RFC3339 时刻，可含小数秒；不包含）")
523		fs.StringVar(&assetID, "asset-id", "", "企业资产编号（可选；缺省统计全部资产）")
524		if err := parseFlags(fs, args); err != nil {
525			return err
526		}
527		if err := requireFlag(fs, startText, "start"); err != nil {
528			return err
529		}
530		if err := requireFlag(fs, endText, "end"); err != nil {
531			return err
532		}
533		start, err := time.Parse(time.RFC3339, startText)
534		if err != nil {
535			return &usageError{msg: fmt.Sprintf("--start 不是带时区的 RFC3339 时刻 %q: %s", startText, err)}
536		}
537		end, err := time.Parse(time.RFC3339, endText)
538		if err != nil {
539			return &usageError{msg: fmt.Sprintf("--end 不是带时区的 RFC3339 时刻 %q: %s", endText, err)}
540		}
541		if !start.Before(end) {
542			return &usageError{msg: fmt.Sprintf("--start（%s）须早于 --end（%s）", startText, endText)}
543		}
544	
545		// openStore 已先做整库一致性检查：损坏或关联矛盾按原规则拒绝（退出码 1）。
546		s, err := openStore(opts.dataDir)
547		if err != nil {
548			return err
549		}
550	
551		var ids []string
552		if assetID != "" {
553			// 未知资产在统计前拒绝（退出码 1）。
554			if s.findAsset(assetID) == nil {
555				return fmt.Errorf("未知资产编号 %q", assetID)
556			}
557			ids = []string{assetID}
558		} else {
559			ids = s.allAssetIDs()
560			if len(ids) == 0 {
561				fmt.Fprintln(w, "没有记录。")
562				fmt.Fprintln(w, "合计: 0 秒")
563				return nil
564			}
565		}
566	
567		// 先算完全部结果再输出：任一资产存在时间异常时整体失败，不输出部分结果。
568		results, err := s.downtimeForAssets(ids, start, end)
569		if err != nil {
570			return err
571		}
572		var total int64
573		if len(results) == 1 {
574			r := results[0]
575			fmt.Fprintf(w, "资产编号: %s\n", r.AssetID)
576			fmt.Fprintf(w, "名称: %s\n", r.Name)
577			fmt.Fprintf(w, "停机秒数: %d\n", r.Seconds)
578			total = r.Seconds
579		} else {
580			fmt.Fprintf(w, "共 %d 项资产:\n", len(results))
581			for _, r := range results {
582				fmt.Fprintf(w, "%s\t%s\t%d\n", r.AssetID, r.Name, r.Seconds)
583				total += r.Seconds
584			}
585		}
586		fmt.Fprintf(w, "合计: %d 秒\n", total)
587		return nil
588	}
589

