1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"strings"
14		"time"
15	)
16	
17	// 资产状态、工单状态与履历类型。
18	const (
19		statusAvailable = "可用"
20		statusRepairing = "维修中"
21		ticketOpen      = "未关闭"
22		ticketClosed    = "已关闭"
23		ticketCancelled = "已取消"
24	
25		eventReport = "报修"
26		eventClose  = "关闭"
27		eventCancel = "取消"
28		eventAssign = "派工"
29	
30		storeVersion = 1
31		dataFileName = "caretrack.json"
32	)
33	
34	var (
35		errNotFound = errors.New("not found")
36		errConflict = errors.New("conflict")
37	)
38	
39	// Asset 为登记的设备资产，ID 即企业资产编号。
40	type Asset struct {
41		ID       string `json:"id"`
42		Name     string `json:"name"`
43		Location string `json:"location"`
44		Status   string `json:"status"`
45	}
46	
47	// Ticket 为维修工单。Assignee 为当前（或终结前最后）负责人，空表示未派工；
48	// AssignedAt/AssignNote 为最近一次派工的变更时间与说明。
49	type Ticket struct {
50		ID           string `json:"id"`
51		AssetID      string `json:"asset_id"`
52		Description  string `json:"description"`
53		RequestID    string `json:"request_id"`
54		Status       string `json:"status"`
55		Result       string `json:"result,omitempty"`
56		CreatedAt    string `json:"created_at"`
57		ClosedAt     string `json:"closed_at,omitempty"`
58		CancelReason string `json:"cancel_reason,omitempty"`
59		CancelledAt  string `json:"cancelled_at,omitempty"`
60		Assignee     string `json:"assignee,omitempty"`
61		AssignedAt   string `json:"assigned_at,omitempty"`
62		AssignNote   string `json:"assign_note,omitempty"`
63	}
64	
65	// Event 为履历条目（报修/派工/关闭/取消），Seq 决定操作发生顺序。
66	// From/To 仅派工履历使用：原负责人（首次派工为空，展示为“未派工”）与新负责人。
67	type Event struct {
68		Seq      int       `json:"-"`
69		AssetID  string    `json:"-"`
70		TicketID string    `json:"-"`
71		Kind     string    `json:"-"`
72		Content  string    `json:"-"`
73		From     string    `json:"-"`
74		To       string    `json:"-"`
75		Time     time.Time `json:"-"`
76	}
77	
78	// eventJSON 与 Event 对应，时间以 RFC3339 文本持久化。
79	type eventJSON struct {
80		Seq      int    `json:"seq"`
81		AssetID  string `json:"asset_id"`
82		TicketID string `json:"ticket_id"`
83		Kind     string `json:"kind"`
84		Content  string `json:"content"`
85		From     string `json:"from,omitempty"`
86		To       string `json:"to,omitempty"`
87		Time     string `json:"time"`
88	}
89	
90	func (e Event) toJSON() eventJSON {
91		return eventJSON{
92			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
93			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To,
94			Time: e.Time.Format(time.RFC3339),
95		}
96	}
97	
98	func (e eventJSON) toEvent() (Event, error) {
99		t, err := time.Parse(time.RFC3339, e.Time)
100		if err != nil {
101			return Event{}, fmt.Errorf("履历时间格式无效 %q: %w", e.Time, err)
102		}
103		return Event{
104			Seq: e.Seq, AssetID: e.AssetID, TicketID: e.TicketID,
105			Kind: e.Kind, Content: e.Content, From: e.From, To: e.To, Time: t,
106		}, nil
107	}
108	
109	// requestBinding 记录请求标识与具体报修的绑定，用于去重与冲突拒绝；
110	// 它既不是资产编号也不是工单编号。
111	type requestBinding struct {
112		RequestID   string `json:"request_id"`
113		AssetID     string `json:"asset_id"`
114		Description string `json:"description"`
115		TicketID    string `json:"ticket_id"`
116	}
117	
118	// storeData 是一次成功写操作共同生效的完整业务数据。
119	type storeData struct {
120		Version       int              `json:"version"`
121		Assets        []*Asset         `json:"assets"`
122		Tickets       []*Ticket        `json:"tickets"`
123		Events        []Event          `json:"-"`
124		EventsJSON    []eventJSON      `json:"events"`
125		Requests      []requestBinding `json:"requests"`
126		NextTicketSeq int              `json:"next_ticket_seq"`
127	}
128	
129	type store struct {
130		dir  string
131		data *storeData
132		now  func() time.Time
133	}
134	
135	func newStoreData() *storeData {
136		return &storeData{
137			Version:       storeVersion,
138			Assets:        []*Asset{},
139			Tickets:       []*Ticket{},
140			Events:        []Event{},
141			EventsJSON:    []eventJSON{},
142			Requests:      []requestBinding{},
143			NextTicketSeq: 1,
144		}
145	}
146	
147	// openStore 打开数据目录：目录/文件不存在时视为空库（首次保存时初始化）；
148	// 已有文件为空或无法解析时报告错误并保留原文件，绝不当空库覆盖。
149	func openStore(dir string) (*store, error) {
150		path := filepath.Join(dir, dataFileName)
151		raw, err := os.ReadFile(path)
152		if err != nil {
153			if errors.Is(err, os.ErrNotExist) {
154				return &store{dir: dir, data: newStoreData(), now: time.Now}, nil
155			}
156			return nil, fmt.Errorf("读取数据文件失败: %w", err)
157		}
158		if len(bytes.TrimSpace(raw)) == 0 {
159			return nil, fmt.Errorf("数据文件 %s 已损坏：文件为空（原文件已保留，未做任何修改）", path)
160		}
161		var d storeData
162		if err := json.Unmarshal(raw, &d); err != nil {
163			return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
164		}
165		if d.EventsJSON != nil {
166			d.Events = make([]Event, len(d.EventsJSON))
167			for i, ej := range d.EventsJSON {
168				ev, err := ej.toEvent()
169				if err != nil {
170					return nil, fmt.Errorf("数据文件 %s 已损坏：%w（原文件已保留，未做任何修改）", path, err)
171				}
172				d.Events[i] = ev
173			}
174		}
175		if err := validateData(&d); err != nil {
176			return nil, fmt.Errorf("数据文件 %s 内容相互矛盾：%w（原文件已保留，未做任何修改）", path, err)
177		}
178		return &store{dir: dir, data: &d, now: time.Now}, nil
179	}
180	
181	// parseTicketSeq 解析 T 加补零正整数序号形式的工单编号，返回序号。
182	// 编号必须与 fmt.Sprintf("T%04d", n)（n ≥ 1）完全一致，否则视为非法。
183	func parseTicketSeq(id string) (int, bool) {
184		if !strings.HasPrefix(id, "T") {
185			return 0, false
186		}
187		n, err := strconv.Atoi(id[1:])
188		if err != nil || n < 1 {
189			return 0, false
190		}
191		if fmt.Sprintf("T%04d", n) != id {
192			return 0, false
193		}
194		return n, true
195	}
196	
197	// validateData 校验整份业务数据的内部一致性。任何矛盾都会返回指明问题类别
198	// （计数器/请求绑定/状态/履历）的错误；调用方必须拒绝查询与写入并保留原文件。
199	// 不做任何修复：不补字段、不重编号、不删除记录。
200	func validateData(d *storeData) error {
201		if d.Version != storeVersion {
202			return fmt.Errorf("不支持的数据版本 %d", d.Version)
203		}
204		if d.Assets == nil || d.Tickets == nil || d.Requests == nil || d.EventsJSON == nil || d.Events == nil {
205			return errors.New("缺少必要的数据段")
206		}
207		assets := map[string]*Asset{}
208		for _, a := range d.Assets {
209			if a == nil || a.ID == "" || a.Name == "" || a.Location == "" {
210				return errors.New("数据矛盾：存在字段不完整的资产记录")
211			}
212			if a.Status != statusAvailable && a.Status != statusRepairing {
213				return fmt.Errorf("状态矛盾：资产 %s 状态无效 %q", a.ID, a.Status)
214			}
215			if assets[a.ID] != nil {
216				return fmt.Errorf("数据矛盾：资产编号 %s 重复", a.ID)
217			}
218			assets[a.ID] = a
219		}
220		tickets := map[string]*Ticket{}
221		maxTicketSeq := 0
222		for _, t := range d.Tickets {
223			if t == nil || t.ID == "" || t.AssetID == "" || t.RequestID == "" || t.Description == "" || t.CreatedAt == "" {
224				return errors.New("数据矛盾：存在字段不完整的工单记录（工单描述不能为空）")
225			}
226			n, ok := parseTicketSeq(t.ID)
227			if !ok {
228				return fmt.Errorf("计数器矛盾：工单编号 %q 不是 T 加补零正整数序号的形式", t.ID)
229			}
230			if n > maxTicketSeq {
231				maxTicketSeq = n
232			}
233			if t.Status != ticketOpen && t.Status != ticketClosed && t.Status != ticketCancelled {
234				return fmt.Errorf("状态矛盾：工单 %s 状态无效 %q", t.ID, t.Status)
235			}
236			if assets[t.AssetID] == nil {
237				return fmt.Errorf("数据矛盾：工单 %s 引用了不存在的资产 %s", t.ID, t.AssetID)
238			}
239			if t.Status == ticketClosed && (t.Result == "" || t.ClosedAt == "") {
240				return fmt.Errorf("状态矛盾：已关闭工单 %s 缺少维修结果或关闭时间", t.ID)
241			}
242			if t.Status == ticketCancelled && (t.CancelReason == "" || t.CancelledAt == "") {
243				return fmt.Errorf("状态矛盾：已取消工单 %s 缺少取消理由或取消时间", t.ID)
244			}
245			if t.Status != ticketClosed && (t.Result != "" || t.ClosedAt != "") {
246				return fmt.Errorf("状态矛盾：非已关闭工单 %s 不应带有维修结果或关闭时间", t.ID)
247			}
248			if t.Status != ticketCancelled && (t.CancelReason != "" || t.CancelledAt != "") {
249				return fmt.Errorf("状态矛盾：非已取消工单 %s 不应带有取消理由或取消时间", t.ID)
250			}
251			if t.Assignee == "" {
252				if t.AssignedAt != "" || t.AssignNote != "" {
253					return fmt.Errorf("状态矛盾：未派工工单 %s 不应带有派工时间或派工说明", t.ID)
254				}
255			} else if t.AssignedAt == "" || t.AssignNote == "" {
256				return fmt.Errorf("状态矛盾：已派工工单 %s 缺少派工时间或派工说明", t.ID)
257			}
258			if tickets[t.ID] != nil {
259				return fmt.Errorf("数据矛盾：工单编号 %s 重复", t.ID)
260			}
261			tickets[t.ID] = t
262		}
263		// 下一工单序号必须为正并大于全部已用序号（允许有间隔）。
264		if d.NextTicketSeq < 1 || d.NextTicketSeq <= maxTicketSeq {
265			return fmt.Errorf("计数器矛盾：下一工单序号 %d 必须为正并大于全部已用序号（当前最大 %d）",
266				d.NextTicketSeq, maxTicketSeq)
267		}
268		// 请求绑定：每张工单恰有一条绑定，且请求标识、资产、描述、工单编号完全一致。
269		boundReq := map[string]bool{}
270		boundTicket := map[string]bool{}
271		for _, r := range d.Requests {
272			if r.RequestID == "" || r.AssetID == "" || r.Description == "" || r.TicketID == "" {
273				return errors.New("请求绑定矛盾：存在字段不完整的请求绑定记录")
274			}
275			if boundReq[r.RequestID] {
276				return fmt.Errorf("请求绑定矛盾：请求标识 %s 被绑定多次", r.RequestID)
277			}
278			boundReq[r.RequestID] = true
279			t := tickets[r.TicketID]
280			if t == nil {
281				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的工单 %s 不存在", r.RequestID, r.TicketID)
282			}
283			if t.RequestID != r.RequestID {
284				return fmt.Errorf("请求绑定矛盾：工单 %s 的请求标识为 %s，绑定记录却来自请求 %s",
285					r.TicketID, t.RequestID, r.RequestID)
286			}
287			if r.AssetID != t.AssetID || r.Description != t.Description {
288				return fmt.Errorf("请求绑定矛盾：请求标识 %s 绑定的资产编号或故障描述与工单 %s 不一致",
289					r.RequestID, t.ID)
290			}
291			boundTicket[r.TicketID] = true
292		}
293		for _, t := range d.Tickets {
294			if !boundTicket[t.ID] {
295				return fmt.Errorf("请求绑定矛盾：工单 %s 缺少对应的报修请求绑定", t.ID)
296			}
297		}
298		// 状态：每项资产最多一张未关闭工单，有则“维修中”，无则“可用”。
299		openCount := map[string]int{}
300		for _, t := range d.Tickets {
301			if t.Status == ticketOpen {
302				openCount[t.AssetID]++
303			}
304		}
305		for _, a := range d.Assets {
306			c := openCount[a.ID]
307			if c > 1 {
308				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，最多允许一张", a.ID, c)
309			}
310			want := statusAvailable
311			if c == 1 {
312				want = statusRepairing
313			}
314			if a.Status != want {
315				return fmt.Errorf("状态矛盾：资产 %s 有 %d 张未关闭工单，状态应为 %s，实际为 %s",
316					a.ID, c, want, a.Status)
317			}
318		}
319		// 履历：序号全库唯一且为正整数；归属、内容与工单一致。
320		seenSeq := map[int]bool{}
321		reportSeq := map[string]int{}
322		closeSeq := map[string]int{}
323		cancelSeq := map[string]int{}
324		reportCount := map[string]int{}
325		closeCount := map[string]int{}
326		cancelCount := map[string]int{}
327		for i := range d.Events {
328			e := &d.Events[i]
329			if e.Seq < 1 {
330				return fmt.Errorf("履历矛盾：履历序号 %d 不是正整数", e.Seq)
331			}
332			if seenSeq[e.Seq] {
333				return fmt.Errorf("履历矛盾：履历序号 %d 重复", e.Seq)
334			}
335			seenSeq[e.Seq] = true
336			if e.AssetID == "" || e.TicketID == "" || e.Kind == "" || e.Content == "" {
337				return errors.New("履历矛盾：存在字段不完整的履历记录")
338			}
339			if e.Kind != eventAssign && (e.From != "" || e.To != "") {
340				return fmt.Errorf("履历矛盾：履历序号 %d 的 %s 记录不应带有派工人员字段", e.Seq, e.Kind)
341			}
342			if e.Kind == eventAssign {
343				if e.To == "" {
344					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录缺少新负责人", e.Seq)
345				}
346				if e.From == e.To {
347					return fmt.Errorf("履历矛盾：履历序号 %d 的派工记录新负责人与原负责人相同", e.Seq)
348				}
349			}
350			t := tickets[e.TicketID]
351			if t == nil || assets[e.AssetID] == nil {
352				return fmt.Errorf("履历矛盾：履历序号 %d 引用了不存在的资产或工单", e.Seq)
353			}
354			if e.AssetID != t.AssetID {
355				return fmt.Errorf("履历矛盾：履历序号 %d 的资产 %s 与工单 %s 归属的资产 %s 不一致",
356					e.Seq, e.AssetID, t.ID, t.AssetID)
357			}
358			switch e.Kind {
359			case eventReport:
360				if e.Content != t.Description {
361					return fmt.Errorf("履历矛盾：工单 %s 的报修履历内容与故障描述不一致", t.ID)
362				}
363				reportCount[t.ID]++
364				reportSeq[t.ID] = e.Seq
365			case eventClose:
366				if e.Content != t.Result {
367					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历内容与维修结果不一致", t.ID)
368				}
369				closeCount[t.ID]++
370				closeSeq[t.ID] = e.Seq
371			case eventCancel:
372				if e.Content != t.CancelReason {
373					return fmt.Errorf("履历矛盾：工单 %s 的取消履历内容与取消理由不一致", t.ID)
374				}
375				cancelCount[t.ID]++
376				cancelSeq[t.ID] = e.Seq
377			case eventAssign:
378				// 内容即派工说明（非空已检查）；派工链的接续与工单负责人一致性
379				// 在下方按序号重放时核对。
380			default:
381				return fmt.Errorf("履历矛盾：履历序号 %d 的事件类型无效 %q", e.Seq, e.Kind)
382			}
383		}
384		for _, t := range d.Tickets {
385			if reportCount[t.ID] != 1 {
386				return fmt.Errorf("履历矛盾：工单 %s 应有恰一条报修履历，实际 %d 条", t.ID, reportCount[t.ID])
387			}
388			if t.Status == ticketClosed {
389				if closeCount[t.ID] != 1 {
390					return fmt.Errorf("履历矛盾：已关闭工单 %s 应有恰一条关闭履历，实际 %d 条", t.ID, closeCount[t.ID])
391				}
392				if closeSeq[t.ID] <= reportSeq[t.ID] {
393					return fmt.Errorf("履历矛盾：工单 %s 的关闭履历（序号 %d）不在报修履历（序号 %d）之后",
394						t.ID, closeSeq[t.ID], reportSeq[t.ID])
395				}
396			} else if closeCount[t.ID] != 0 {
397				return fmt.Errorf("履历矛盾：非已关闭工单 %s 不得有关闭履历", t.ID)
398			}
399			if t.Status == ticketCancelled {
400				if cancelCount[t.ID] != 1 {
401					return fmt.Errorf("履历矛盾：已取消工单 %s 应有恰一条取消履历，实际 %d 条", t.ID, cancelCount[t.ID])
402				}
403				if cancelSeq[t.ID] <= reportSeq[t.ID] {
404					return fmt.Errorf("履历矛盾：工单 %s 的取消履历（序号 %d）不在报修履历（序号 %d）之后",
405						t.ID, cancelSeq[t.ID], reportSeq[t.ID])
406				}
407			} else if cancelCount[t.ID] != 0 {
408				return fmt.Errorf("履历矛盾：非已取消工单 %s 不得有取消履历", t.ID)
409			}
410		}
411		// 按履历序号推进，重放得到的工单与资产状态须与保存的状态相符；
412		// 同一资产的上一张工单必须先关闭或取消才可产生下一张报修。
413		sorted := make([]Event, len(d.Events))
414		copy(sorted, d.Events)
415		sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Seq < sorted[j].Seq })
416		derivedTicket := map[string]string{}
417		derivedOpen := map[string]string{}
418		derivedAssignee := map[string]string{}
419		derivedNote := map[string]string{}
420		for _, e := range sorted {
421			switch e.Kind {
422			case eventReport:
423				if derivedTicket[e.TicketID] != "" {
424					return fmt.Errorf("履历矛盾：工单 %s 被重复报修", e.TicketID)
425				}
426				if prev := derivedOpen[e.AssetID]; prev != "" {
427					return fmt.Errorf("履历矛盾：资产 %s 的上一张工单 %s 尚未结束就产生了工单 %s 的报修",
428						e.AssetID, prev, e.TicketID)
429				}
430				derivedTicket[e.TicketID] = ticketOpen
431				derivedOpen[e.AssetID] = e.TicketID
432			case eventAssign:
433				if derivedTicket[e.TicketID] != ticketOpen {
434					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现派工履历", e.TicketID)
435				}
436				if e.From != derivedAssignee[e.TicketID] {
437					return fmt.Errorf("履历矛盾：工单 %s 的派工履历（序号 %d）原负责人 %q 与上次记录不接续",
438						e.TicketID, e.Seq, e.From)
439				}
440				derivedAssignee[e.TicketID] = e.To
441				derivedNote[e.TicketID] = e.Content
442			case eventClose:
443				if derivedTicket[e.TicketID] != ticketOpen {
444					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现关闭履历", e.TicketID)
445				}
446				derivedTicket[e.TicketID] = ticketClosed
447				delete(derivedOpen, e.AssetID)
448			case eventCancel:
449				if derivedTicket[e.TicketID] != ticketOpen {
450					return fmt.Errorf("履历矛盾：工单 %s 在未处于未关闭状态时出现取消履历", e.TicketID)
451				}
452				derivedTicket[e.TicketID] = ticketCancelled
453				delete(derivedOpen, e.AssetID)
454			}
455		}
456		for _, t := range d.Tickets {
457			if derivedTicket[t.ID] != t.Status {
458				return fmt.Errorf("状态矛盾：按履历推进得到工单 %s 状态为 %s，与保存的 %s 不符",
459					t.ID, derivedTicket[t.ID], t.Status)
460			}
461			// 由履历推出的最后负责人须与工单记录一致；无派工履历则必须未派工。
462			if derivedAssignee[t.ID] != t.Assignee {
463				return fmt.Errorf("状态矛盾：按履历推出工单 %s 最后负责人为 %q，与保存的 %q 不符",
464					t.ID, derivedAssignee[t.ID], t.Assignee)
465			}
466			if t.Assignee != "" && derivedNote[t.ID] != t.AssignNote {
467				return fmt.Errorf("状态矛盾：工单 %s 保存的派工说明与最后一次派工履历不一致", t.ID)
468			}
469		}
470		for _, a := range d.Assets {
471			want := statusAvailable
472			if derivedOpen[a.ID] != "" {
473				want = statusRepairing
474			}
475			if a.Status != want {
476				return fmt.Errorf("状态矛盾：按履历推进得到资产 %s 状态为 %s，与保存的 %s 不符",
477					a.ID, want, a.Status)
478			}
479		}
480		return nil
481	}
