580	// nextEventSeq 返回下一条履历应使用的全库唯一正整数序号；计数器耗尽时报错。
581	func (s *store) nextEventSeq() (int, error) {
582		maxSeq := 0
583		for _, e := range s.data.Events {
584			if e.Seq > maxSeq {
585				maxSeq = e.Seq
586			}
587		}
588		if maxSeq == math.MaxInt {
589			return 0, fmt.Errorf("%w: 履历序号计数器已耗尽，无法追加履历", errConflict)
590		}
591		return maxSeq + 1, nil
592	}
