594	// appendEvent 以给定序号追加履历。调用方须先通过 nextEventSeq 取得序号，
595	// 确保任何失败路径都不会在部分变更后才报错。from/to 仅派工履历使用。
596	func (s *store) appendEvent(seq int, assetID, ticketID, kind, content, from, to string) {
597		s.data.Events = append(s.data.Events, Event{
598			Seq:      seq,
599			AssetID:  assetID,
600			TicketID: ticketID,
601			Kind:     kind,
602			Content:  content,
603			From:     from,
604			To:       to,
605			Time:     s.now(),
606		})
607	}
