618	// report 创建报修工单。返回 (工单, 是否为去重重放, 错误)。
619	// 所有失败路径都不修改任何业务数据，也不会绑定新的请求标识。
620	func (s *store) report(assetID, description, requestID string) (*Ticket, bool, error) {
621		// 已有绑定：相同资产+描述 => 返回原工单（无论其是否已关闭、是否已有新工单）；
622		// 资产或描述不同 => 拒绝。
623		if r := s.findRequest(requestID); r != nil {
624			if r.AssetID != assetID || r.Description != description {
625				return nil, false, fmt.Errorf(
626					"%w: 请求标识 %q 已用于资产 %q 的另一笔报修，不能搭配不同的资产编号或故障描述",
627					errConflict, requestID, r.AssetID)
628			}
629			t := s.findTicket(r.TicketID)
630			if t == nil {
631				return nil, false, fmt.Errorf("数据内部错误：请求标识 %q 绑定的工单不存在", requestID)
632			}
633			return t, true, nil
634		}
635	
636		asset := s.findAsset(assetID)
637		if asset == nil {
638			return nil, false, fmt.Errorf("%w: 未知资产编号 %q", errNotFound, assetID)
639		}
640		if t := s.openTicketOf(assetID); t != nil {
641			return nil, false, fmt.Errorf("%w: 资产 %s 已有未关闭工单 %s", errConflict, assetID, t.ID)
642		}
643		// 先确认编号与履历计数器都能推进，再修改任何业务数据：
644		// 编号耗尽时拒绝新报修，不消耗编号，也不绑定请求标识。
645		seq := s.data.NextTicketSeq
646		if seq < 1 || seq == math.MaxInt {
647			return nil, false, fmt.Errorf("%w: 工单编号计数器已耗尽，无法分配新工单编号", errConflict)
648		}
649		eventSeq, err := s.nextEventSeq()
650		if err != nil {
651			return nil, false, err
652		}
653		t := &Ticket{
654			ID:          fmt.Sprintf("T%04d", seq),
655			AssetID:     assetID,
656			Description: description,
657			RequestID:   requestID,
658			Status:      ticketOpen,
659			CreatedAt:   s.now().Format(time.RFC3339),
660		}
661		s.data.NextTicketSeq = seq + 1
662		s.data.Tickets = append(s.data.Tickets, t)
663		s.data.Requests = append(s.data.Requests, requestBinding{
664			RequestID:   requestID,
665			AssetID:     assetID,
666			Description: description,
667			TicketID:    t.ID,
668		})
669		asset.Status = statusRepairing
670		s.appendEvent(eventSeq, assetID, t.ID, eventReport, description, "", "")
671		return t, false, nil
672	}
673	
674	// closeTicket 关闭未关闭工单并把资产恢复为可用。
675	// 失败路径不修改任何业务数据。
676	func (s *store) closeTicket(ticketID, result string) (*Ticket, *Asset, error) {
677		t := s.findTicket(ticketID)
678		if t == nil {
679			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
680		}
681		if t.Status == ticketCancelled {
682			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能关闭", errConflict, ticketID)
683		}
684		if t.Status != ticketOpen {
685			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能重复关闭", errConflict, ticketID)
686		}
687		asset := s.findAsset(t.AssetID)
688		if asset == nil {
689			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
690		}
691		eventSeq, err := s.nextEventSeq()
692		if err != nil {
693			return nil, nil, err
694		}
695		t.Status = ticketClosed
696		t.Result = result
697		t.ClosedAt = s.now().Format(time.RFC3339)
698		asset.Status = statusAvailable
699		s.appendEvent(eventSeq, asset.ID, t.ID, eventClose, result, "", "")
700		return t, asset, nil
701	}
702	
703	// cancelTicket 取消未关闭工单并把资产恢复为可用。取消是终态，但不代表维修完成：
704	// 不填写维修结果，不删除工单、履历或请求绑定，工单编号不回退也不复用。
705	// 失败路径不修改任何业务数据。
706	func (s *store) cancelTicket(ticketID, reason string) (*Ticket, *Asset, error) {
707		t := s.findTicket(ticketID)
708		if t == nil {
709			return nil, nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
710		}
711		if t.Status == ticketCancelled {
712			return nil, nil, fmt.Errorf("%w: 工单 %s 已取消，不能再次取消", errConflict, ticketID)
713		}
714		if t.Status == ticketClosed {
715			return nil, nil, fmt.Errorf("%w: 工单 %s 已关闭，不能取消", errConflict, ticketID)
716		}
717		asset := s.findAsset(t.AssetID)
718		if asset == nil {
719			return nil, nil, fmt.Errorf("数据内部错误：工单 %s 引用的资产不存在", ticketID)
720		}
721		eventSeq, err := s.nextEventSeq()
722		if err != nil {
723			return nil, nil, err
724		}
725		t.Status = ticketCancelled
726		t.CancelReason = reason
727		t.CancelledAt = s.now().Format(time.RFC3339)
728		asset.Status = statusAvailable
729		s.appendEvent(eventSeq, asset.ID, t.ID, eventCancel, reason, "", "")
730		return t, asset, nil
731	}
732	
733	// assignTicket 为未关闭工单派工或转派：没有负责人时首次派工，已有负责人时
734	// 转派给不同人员。人员标识只是本地文本记录，不对应任何人员账户。
735	// 成功后保存负责人、变更时间与说明，并追加一条含原负责人（首次派工为空，
736	// 展示为“未派工”）、新负责人及说明的派工履历。派工不创建工单、不消耗工单
737	// 编号，也不改变资产状态或报修请求绑定。失败路径不修改任何业务数据。
738	func (s *store) assignTicket(ticketID, assignee, note string) (*Ticket, error) {
739		t := s.findTicket(ticketID)
740		if t == nil {
741			return nil, fmt.Errorf("%w: 未知工单编号 %q", errNotFound, ticketID)
742		}
743		if t.Status == ticketClosed {
744			return nil, fmt.Errorf("%w: 工单 %s 已关闭，不能派工", errConflict, ticketID)
745		}
746		if t.Status == ticketCancelled {
747			return nil, fmt.Errorf("%w: 工单 %s 已取消，不能派工", errConflict, ticketID)
748		}
749		if assignee == "" {
750			return nil, fmt.Errorf("%w: 维修人员标识不能为空", errConflict)
751		}
752		if note == "" {
753			return nil, fmt.Errorf("%w: 派工说明不能为空", errConflict)
754		}
755		if t.Assignee == assignee {
756			return nil, fmt.Errorf("%w: 工单 %s 当前负责人已是 %s，不能重复派给同一人",
757				errConflict, ticketID, assignee)
758		}
759		eventSeq, err := s.nextEventSeq()
760		if err != nil {
761			return nil, err
762		}
763		s.appendEvent(eventSeq, t.AssetID, t.ID, eventAssign, note, t.Assignee, assignee)
764		t.Assignee = assignee
765		t.AssignedAt = s.now().Format(time.RFC3339)
766		t.AssignNote = note
767		return t, nil
768	}
769

