454		if err != nil {
455			t.Fatalf("编号耗尽的合法台账应能加载: %v", err)
456		}
457		if _, _, err := s.report("EQ-1", "卡纸", "req-1"); err != nil {
458			t.Fatalf("既有请求重放不应受编号耗尽影响: %v", err)
459		}
