461			!strings.Contains(err.Error(), "耗尽") {
462			t.Fatalf("编号耗尽时应拒绝新报修，得到 %v", err)
463		}
464		// 查询与关闭已有工单不受影响。
465		var out, errBuf bytes.Buffer
466		if code := run([]string{"list", "--data-dir", dir}, &out, &errBuf); code != 0 {
467			t.Fatalf("编号耗尽时 list 应可用: %s", errBuf.String())
468		}
469		if code := run([]string{"close", "--data-dir", dir, "--ticket-id", "T0001", "--repair-result", "已修复"},
470			&out, &errBuf); code != 0 {
471			t.Fatalf("编号耗尽时关闭已有工单应可用: %s", errBuf.String())
472		}
473		if !strings.Contains(out.String(), "已关闭") {
474			t.Fatalf("关闭输出异常: %s", out.String())
475		}
476		// 关闭后新报修仍被拒绝（编号依旧耗尽）。
477		s2, err := openStore(dir)
478		if err != nil {
479			t.Fatal(err)
480		}
481		if _, _, err := s2.report("EQ-1", "新故障", "req-2"); err == nil {
482			t.Fatal("关闭工单后编号仍然耗尽，新报修应继续被拒绝")
483		}
484	}
